#!/usr/bin/env python3
"""Build the interactive and A3 maps from validated SAO GeoJSON layers."""
from __future__ import annotations

import argparse
import html
import json
from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True)
class LayerSpec:
    filename: str; key: str; name: str; color: str; default: bool
    logical_count: int | None = None; note: str = ""


SPECS = (
    LayerSpec("sao_boundary_wgs84.geojson", "boundary", "Граница САО (включая Молжаниновский район)", "#6a1b9a", True, None, "Визуализационный контур; Молжаниновский район включён, подпись на карте скрыта."),
    LayerSpec("sao_wave1_complete_wgs84.geojson", "wave1", "ОДХ: 1-я очередь (97 позиций)", "#e53935", True, 97, "94 геометрии ОДХ + 3 ориентировочных маркера ТПУ/площадки."),
    LayerSpec("sao_remaining_wgs84.geojson", "remaining", "ОДХ: остальные (594 без очередности)", "#757575", True, 594, "Очередность для этих объектов не определена."),
    LayerSpec("sao_pgm_containers_wgs84.geojson", "pgm", "Контейнеры ПГМ (215 привязок к ОДХ; всего 451 шт.)", "#c05600", False, 451, "Точки — представители геометрии ОДХ, а не точные координаты контейнеров."),
    LayerSpec("sao_snow_storage_sites_wgs84.geojson", "snow", "Временное складирование снега (27 кандидатов, 2025–2026)", "#039be5", False, 27, "Адреса из плана-графика; геокодерные кандидаты требуют служебной сверки."),
    LayerSpec("sao_state_healthcare_confirmed_wgs84.geojson", "healthcare", "Государственные учреждения здравоохранения (10 подтверждено)", "#c62828", True, 10, "Адрес и статус подтверждены официальным источником; координаты — геокодированные точки."),
    LayerSpec("sao_fire_hydrants_address_centroids_wgs84.geojson", "hydrants", "Пожарные гидранты (24 адресных центроида)", "#d32f2f", False, 24, "Временная адресная привязка; требуется служебная сверка точных координат гидрантов."),
)


BRAND_MARK_IMG_B64 = ""

ICONS = {
    "boundary": '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2 L20.5 7 L20.5 17 L12 22 L3.5 17 L3.5 7 Z" stroke-dasharray="3 2.2"/></svg>',
    "wave1": '<svg viewBox="0 0 24 24" width="18" height="18" fill="none"><g stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><rect x="8" y="2" width="8" height="20" rx="2.5" stroke-width="1.8"/><path d="M12 5.5 L12 8 M12 11 L12 13 M12 16 L12 18.5" stroke-width="1.8"/></g><circle cx="17.5" cy="4.5" r="4.6" fill="currentColor" stroke="#fff" stroke-width="1"/><text x="17.5" y="6.6" text-anchor="middle" font-family="Arial,sans-serif" font-size="6.4" font-weight="700" fill="#fff">1</text></svg>',
    "remaining": '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><rect x="8" y="2" width="8" height="20" rx="2.5" stroke-width="1.8"/><path d="M12 5.5 L12 8 M12 11 L12 13 M12 16 L12 18.5" stroke-width="1.8"/></svg>',
    "pgm": '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="6" y="4" width="12" height="16" rx="2.2"/><path d="M6 9 H18 M6 14 H18"/></svg>',
    "snow": '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M12 2 V22 M4.4 7 L19.6 17 M19.6 7 L4.4 17"/><path d="M12 2 L9.6 4.4 M12 2 L14.4 4.4 M12 22 L9.6 19.6 M12 22 L14.4 19.6 M4.4 7 L4.4 9.8 M4.4 7 L7 6.1 M19.6 17 L19.6 14.2 M19.6 17 L17 17.9 M19.6 7 L19.6 9.8 M19.6 7 L17 6.1 M4.4 17 L4.4 14.2 M4.4 17 L7 17.9"/></svg>',
    "healthcare": '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3.5" y="3.5" width="17" height="17" rx="4.5"/><path d="M12 7.5 V16.5 M7.5 12 H16.5"/></svg>',
}


def symbol_svg(kind: str, color: str) -> str:
    """Return the approved inline SVG used by thematic ODH point markers."""
    icon = {
        "wave1": "road", "remaining": "road", "pgm": "container",
        "snow": "snowflake", "healthcare": "medical", "hydrants": "hydrant",
    }[kind]
    common = f'data-kind="{icon}" viewBox="0 0 24 24" aria-hidden="true" style="--symbol-color:{color}"'
    if icon == "road":
        path = '<rect x="8" y="2" width="8" height="20" rx="2.5"/><path d="M12 5.5V8M12 11V13M12 16V18.5"/>'
    elif icon == "container":
        path = '<rect x="6" y="4" width="12" height="16" rx="2.2"/><path d="M6 9H18M6 14H18"/>'
    elif icon == "snowflake":
        path = '<path d="M12 2V22M4.4 7L19.6 17M19.6 7L4.4 17"/><path d="M12 2L9.6 4.4M12 2L14.4 4.4M12 22L9.6 19.6M12 22L14.4 19.6M4.4 7V9.8M4.4 7L7 6.1M19.6 17V14.2M19.6 17L17 17.9M19.6 7V9.8M19.6 7L17 6.1M4.4 17V14.2M4.4 17L7 17.9"/>'
    elif icon == "hydrant":
        path = '<path d="M7 21h10M9 21V11h6v10M7 11h10M12 11V5M9 5h6M6 14H3M18 14h3"/><circle cx="12" cy="5" r="2.2"/>'
    else:
        path = '<rect x="3.5" y="3.5" width="17" height="17" rx="4.5"/><path d="M12 7.5V16.5M7.5 12H16.5"/>'
    return f'<svg {common} fill="none" stroke="var(--symbol-color)" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{path}</svg>'


def load_layers(data_dir: Path) -> list[dict]:
    result = []
    for spec in SPECS:
        data = json.loads((data_dir / spec.filename).read_text(encoding="utf-8"))
        result.append({"spec": spec, "data": data, "feature_count": len(data.get("features", []))})
    return result


def safe_json(value: object) -> str:
    return json.dumps(value, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")


def render_html(layers: list[dict], mode: str) -> str:
    legend = "".join(
        f'<label class="layer-toggle"><input type="checkbox" data-key="{s.key}" {"checked" if s.default else ""} onchange="toggleLayer(this)"><span class="layer-swatch" style="color:{s.color}">{ICONS.get(s.key, "") if s.key == "boundary" else symbol_svg(s.key, s.color)}</span><span>{html.escape(s.name)}</span><span class="layer-count">{s.logical_count or ""}</span></label><p class="layer-note">{html.escape(s.note)}</p>'
        for s in SPECS
    )
    is_print = mode == "print"
    heading = "Карта САО — печать A3" if is_print else "Карта САО — интерактивная"
    print_css = "@page{size:A3 landscape;margin:8mm}.topbar{min-height:13mm;padding:0 4mm}.workspace{height:273mm}.sidebar{width:72mm;padding:4mm}.map-overlay,.panel-actions,.hint{display:none}.layer-note{font-size:8px}.layer-toggle{padding:4px 5px}.section-head{margin-top:6px}" if is_print else "html,body{height:100%}.app{height:100vh}.workspace{height:calc(100vh - 58px)}"
    return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{heading}</title><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><style>
:root{{--ink:#102636;--muted:#71808b;--line:#d9e1e4;--paper:#f7f5ef;--accent:#0d827c;--shadow:0 18px 48px rgba(16,38,54,.16)}}*{{box-sizing:border-box}}html,body{{margin:0;background:#dfe8e8;color:var(--ink);font-family:"Century Gothic","CenturyGothic",AppleGothic,Questrial,Poppins,Arial,sans-serif}}.app{{display:flex;flex-direction:column;overflow:hidden}}.topbar{{z-index:5;display:flex;align-items:center;justify-content:space-between;min-height:58px;padding:0 20px;background:var(--paper);border-bottom:1px solid var(--line)}}.brand{{display:flex;align-items:center;gap:10px;letter-spacing:-.02em}}.brand-mark{{display:grid;place-items:center;width:36px;height:36px;border-radius:10px;background:#fff;border:1px solid var(--line);overflow:hidden;padding:3px}}.brand-mark img{{width:100%;height:100%;object-fit:contain;display:block}}.brand strong{{display:block;font-size:15px;line-height:1.1}}.brand small{{display:block;margin-top:3px;color:var(--muted);font-size:10px;letter-spacing:.08em;text-transform:uppercase}}.topbar-meta{{display:flex;align-items:center;gap:8px;color:#5a6a73;font-size:11px}}.live-dot{{width:7px;height:7px;border-radius:50%;background:#27a875;box-shadow:0 0 0 4px rgba(39,168,117,.13)}}
.workspace{{display:grid;grid-template-columns:350px minmax(0,1fr);min-height:0;flex:1}}.sidebar{{z-index:2;overflow:auto;padding:18px;background:rgba(255,255,255,.97);border-right:1px solid var(--line)}}.panel-heading{{display:flex;align-items:flex-start;justify-content:space-between;gap:8px}}.eyebrow{{display:block;color:var(--accent);font-size:10px;font-weight:800;letter-spacing:.12em}}h1{{margin:5px 0 0;font-size:22px;line-height:1.12}}h2{{margin:0;font-size:14px}}.icon-button{{display:grid;place-items:center;width:44px;height:44px;border:1px solid #8a979c;border-radius:10px;background:#fff;color:var(--ink);font-size:19px;cursor:pointer;transition:border-color .12s,color .12s}}.icon-button:hover{{border-color:var(--accent);color:var(--accent)}}.icon-button:focus-visible{{outline:3px solid var(--accent);outline-offset:2px}}.status{{display:flex;align-items:center;gap:9px;min-height:43px;margin-top:14px;padding:9px 11px;border:1px solid #cfe6df;border-radius:10px;background:#eff9f5;color:#27665a;font-size:11px;line-height:1.35}}.status-dot{{width:7px;height:7px;border-radius:50%;background:#27a875}}.load-retry{{margin-left:auto;min-height:28px;padding:4px 8px;border:1px solid #8a979c;border-radius:7px;background:#fff;color:var(--ink);font:inherit;font-size:10px;cursor:pointer}}.load-retry:hover{{border-color:var(--accent);color:var(--accent)}}.load-retry:focus-visible{{outline:3px solid var(--accent);outline-offset:2px}}.search{{width:100%;min-height:44px;margin-top:11px;padding:10px 11px;border:1px solid #8a979c;border-radius:9px;color:var(--ink);font:inherit;font-size:12px;outline:none;box-sizing:border-box}}.search:focus{{border-color:var(--accent);box-shadow:0 0 0 3px rgba(13,130,124,.12)}}#results{{max-height:100px;overflow:auto}}.search-result{{padding:8px 4px;min-height:44px;box-sizing:border-box;display:flex;align-items:center;border-bottom:1px solid #eef1f1;color:#28655f;font-size:11px;cursor:pointer}}.search-result:hover,.search-result:focus-visible{{background:#eff9f5;outline:2px solid var(--accent);outline-offset:-2px}}.section-head{{display:flex;align-items:baseline;justify-content:space-between;margin:21px 0 9px}}.hint{{color:#64717a;font-size:10px}}.layers{{display:grid;gap:5px}}.layer-toggle{{display:flex;align-items:center;gap:8px;min-height:44px;padding:9px 10px;border:1px solid var(--line);border-radius:10px;color:#40525d;font-size:11px;cursor:pointer;transition:border-color .12s,background .12s}}.layer-toggle:hover{{border-color:var(--accent);background:#f4fbfa}}.layer-toggle:focus-within{{outline:3px solid var(--accent);outline-offset:2px}}.layer-toggle input{{margin:0;accent-color:var(--accent)}}.layer-swatch{{flex:0 0 22px;width:22px;height:22px;display:grid;place-items:center}}.layer-swatch svg{{width:18px;height:18px}}.odh-symbol-marker{{display:block!important;width:32px!important;height:32px!important;margin:0!important;padding:3px!important;border:2px solid #fff!important;border-radius:16px!important;background:#fff!important;box-shadow:0 2px 8px rgba(16,38,54,.5)!important;overflow:hidden!important}}.odh-symbol-marker svg{{display:block!important;width:22px!important;height:22px!important;stroke-width:2.5!important;filter:drop-shadow(0 0 1px rgba(16,38,54,.4))}}.layer-count{{margin-left:auto;color:#5b6870;font:10px ui-monospace,Consolas,monospace}}.layer-note{{margin:0 7px 6px 40px;color:#5c6971;font-size:10px;line-height:1.25}}.panel-actions{{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:15px}}.printbtn,.resetbtn{{min-height:44px;border:1px solid #8a979c;border-radius:9px;background:#fff;color:var(--ink);font:inherit;font-size:11px;cursor:pointer;transition:border-color .12s,color .12s}}.printbtn:hover,.resetbtn:hover{{border-color:var(--accent);color:var(--accent)}}.printbtn:focus-visible,.resetbtn:focus-visible{{outline:3px solid var(--accent);outline-offset:2px}}.details{{padding:10px;border:1px solid var(--line);border-radius:10px;background:#fff;color:#5b6b73;font-size:11px;line-height:1.45}}.legal-note{{margin-top:10px;color:#7b5b30;font-size:10px;line-height:1.35}}.details b{{color:var(--ink)}}.map-wrap{{position:relative;min-width:0;min-height:0;background:#e3eceb}}#map{{width:100%;height:100%}}.map-attribution{{position:absolute;z-index:600;right:8px;bottom:8px;padding:3px 5px;border-radius:3px;background:rgba(247,245,239,.88);color:#4f5d65;font-size:9px;line-height:1.2}}.map-attribution a{{color:inherit}}.map-overlay{{position:absolute;z-index:500;left:16px;bottom:16px;display:flex;flex-direction:column;gap:3px;padding:9px 11px;border:1px solid rgba(215,225,225,.95);border-radius:10px;background:rgba(247,245,239,.94);box-shadow:var(--shadow);color:#61717a;font-size:11px;pointer-events:none}}.map-overlay-title{{color:var(--ink);font-size:10px;font-weight:800;letter-spacing:.1em}}.leaflet-control-attribution{{display:none}}@media(max-width:780px){{.app{{height:auto;min-height:100vh;overflow:visible}}.topbar-meta{{display:none}}.workspace{{grid-template-columns:1fr;grid-template-rows:auto minmax(65vh,1fr);height:auto}}.sidebar{{border-right:0;border-bottom:1px solid var(--line)}}}}{print_css}</style></head><body><div class="app"><header class="topbar"><div class="brand"><span class="brand-mark"><img src="data:image/png;base64,{BRAND_MARK_IMG_B64}" alt="Герб САО"></span><span><strong>Городской атлас САО</strong><small>Дороги · объекты · инфраструктура</small></span></div><div class="topbar-meta"><span class="live-dot"></span><span>Рабочая карта · 24.08.2026</span></div></header><main class="workspace"><aside class="sidebar"><div class="panel-heading"><div><span class="eyebrow">ОБЗОР ТЕРРИТОРИИ</span><h1>Объекты и слои</h1></div><button class="icon-button" type="button" onclick="resetMap()" title="Показать всю карту" aria-label="Показать всю карту">↺</button></div><div class="status"><span class="status-dot"></span><span>688 объектов ОДХ · 97 в первой очереди</span></div><div id="load-status" class="status" role="status" aria-live="polite"><span class="status-dot"></span><span>Подготовка загрузки слоёв…</span></div><input id="search" class="search" type="search" placeholder="Поиск по названию или адресу" aria-label="Поиск по названию или адресу" oninput="searchFeatures()"><div id="results" aria-live="polite"></div><div class="section-head"><h2>Слои карты</h2><span class="hint">включить / скрыть</span></div><section class="layers">{legend}</section><div class="panel-actions"><button class="resetbtn" type="button" onclick="resetMap()" aria-label="Сбросить вид карты">Сбросить вид</button><button class="printbtn" type="button" onclick="printMap()" aria-label="Печать или сохранение в PDF A3">Печать / PDF A3</button></div><section><div class="section-head"><h2>Карточка объекта</h2><span class="hint">по клику</span></div><div id="details" class="details" aria-live="polite">Нажмите на объект на карте — здесь появятся его сведения.</div><p class="legal-note">Красные ориентировочные маркеры: это не юридические/кадастровые границы.</p></section></aside><section class="map-wrap"><div id="map"></div><div class="map-attribution" aria-label="© OpenStreetMap contributors · © CARTO">© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a> · © <a href="https://carto.com/attributions" target="_blank" rel="noopener">CARTO</a></div><div class="map-overlay"><span class="map-overlay-title">ИНТЕРАКТИВНАЯ КАРТА</span><span>Нажмите на объект, чтобы открыть сведения</span></div></section></main></div><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const SYMBOLS={safe_json({s.key: symbol_svg(s.key, s.color) for s in SPECS if s.key != "boundary"})};const map=L.map('map',{{zoomControl:{str(not is_print).lower()},attributionControl:false}});L.tileLayer('https://{{s}}.basemaps.cartocdn.com/light_nolabels/{{z}}/{{x}}/{{y}}{{r}}.png',{{subdomains:'abcd',maxZoom:19,attribution:""}}).addTo(map);const groups={{}},searchIndex=[];let allBounds=null,loadPromise=Promise.resolve();function esc(v){{return String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));}}function setLoadStatus(message,retry=false){{const status=document.getElementById('load-status');status.innerHTML='<span class="status-dot"></span><span>'+esc(message)+'</span>'+(retry?'<button type="button" class="load-retry" onclick="retryLoad()">Повторить загрузку</button>':'');}}function assertOk(response){{if(!response.ok)throw new Error(response.url+': HTTP '+response.status);return response;}}function displayDetails(p){{document.getElementById('details').innerHTML=popupHtml(p);}}function popupHtml(p){{const labels={{address:'Адрес',organization:'Организация',ownership:'Собственник',verification_status:'Статус проверки',official_source:'Официальный источник',official_evidence:'Подтверждение'}};const skip=new Set(['name','__symbolSvg','latitude','longitude','yandex_maps_search','2gis_search','google_maps_search','note']);const rows=Object.entries(p||{{}}).filter(([k,v])=>!skip.has(k)&&v!==null&&v!==undefined&&v!=='').map(([k,v])=>'<b>'+esc(labels[k]||k)+':</b> '+esc(v));const links=[['official_source','Источник'],['yandex_maps_search','Яндекс Карты'],['2gis_search','2ГИС'],['google_maps_search','Google Карты']].filter(([k])=>p?.[k]).map(([k,t])=>'<a target="_blank" rel="noopener" href="'+esc(p[k])+'">'+t+'</a>');return '<b>'+esc(p?.name||'Объект')+'</b>'+ (rows.length?'<br>'+rows.join('<br>'):'')+(links.length?'<div style="margin-top:8px;display:flex;gap:7px;flex-wrap:wrap">'+links.join(' · ')+'</div>':'');}}function clearMapLayers(){{Object.values(groups).forEach(group=>map.removeLayer(group));Object.keys(groups).forEach(key=>delete groups[key]);searchIndex.length=0;allBounds=null;}}function prepareGeojson(geojson,layer){{return {{...geojson,features:(geojson.features||[]).map(feature=>{{if(['Point','MultiPoint'].includes(feature.geometry?.type)){{return {{...feature,properties:{{...(feature.properties||{{}}),__symbolSvg:SYMBOLS[layer.key]||''}}}};}}return feature;}})}};}}function addLayers(loaded){{loaded.forEach(item=>{{const group=L.geoJSON(prepareGeojson(item.geojson,item),{{style:f=>{{const b=String(f.properties?.feature_kind||'').startsWith('boundary');return {{color:item.color,weight:b?5:2,opacity:.9,fillColor:item.color,fillOpacity:b?0.18:0,dashArray:b?'8 5':null}};}},pointToLayer:(feature,latlng)=>L.marker(latlng,{{icon:L.divIcon({{className:'odh-symbol-marker',html:feature.properties.__symbolSvg,iconSize:[32,32],iconAnchor:[16,16]}})}}),onEachFeature:(f,l)=>{{l.bindPopup(popupHtml(f.properties));l.on('click',()=>displayDetails(f.properties));searchIndex.push({{layer:l,text:JSON.stringify(f.properties||{{}}).toLowerCase()}});}}}});groups[item.key]=group;if(item.default)group.addTo(map);const b=group.getBounds();if(b.isValid())allBounds=allBounds?allBounds.extend(b):b;}});resetMap();}}async function loadMapLayers(){{clearMapLayers();setLoadStatus('Загрузка слоёв…');try{{const manifest=await fetch('layers.json').then(assertOk).then(r=>r.json());const loaded=await Promise.all(manifest.layers.map(async layer=>({{...layer,geojson:await fetch(layer.url).then(assertOk).then(r=>r.json())}})));addLayers(loaded);setLoadStatus(`Готово: ${{loaded.length}} слоёв.`);}}catch(error){{setLoadStatus('Не удалось загрузить слои: '+error.message,true);throw error;}}}}function retryLoad(){{loadPromise=loadMapLayers();loadPromise.catch(()=>{{}});}}function resetMap(){{if(allBounds)map.fitBounds(allBounds,{{padding:[24,24]}});}}function toggleLayer(el){{const group=groups[el.dataset.key];if(!group)return;if(el.checked)group.addTo(map);else map.removeLayer(group);}}function searchFeatures(){{const q=document.getElementById('search').value.trim().toLowerCase(),out=document.getElementById('results');out.innerHTML='';if(q.length<3)return;searchIndex.filter(x=>x.text.includes(q)).slice(0,12).forEach(x=>{{const item=document.createElement('div');item.className='search-result';item.textContent=x.layer.feature.properties?.name||'Объект';item.tabIndex=0;item.setAttribute('role','button');const activate=()=>{{const target=x.layer.getLatLng?x.layer.getLatLng():x.layer.getBounds().getCenter();map.setView(target,16);x.layer.openPopup();displayDetails(x.layer.feature.properties);}};item.onclick=activate;item.onkeydown=e=>{{if(e.key==='Enter'||e.key===' '){{e.preventDefault();activate();}}}};out.appendChild(item);}});}}async function printMap(){{try{{await loadPromise;window.print();}}catch(error){{setLoadStatus('Печать недоступна: сначала загрузите слои.',true);}}}}loadPromise=loadMapLayers();loadPromise.catch(()=>{{}});</script></body></html>'''


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--data-dir", type=Path, required=True)
    parser.add_argument("--output-dir", type=Path, required=True)
    args = parser.parse_args()
    args.output_dir.mkdir(parents=True, exist_ok=True)
    layers = load_layers(args.data_dir)
    for mode, filename in (("interactive", "sao_map_interactive.html"), ("print", "sao_map_print_a3.html")):
        (args.output_dir / filename).write_text(render_html(layers, mode), encoding="utf-8")
    print("Карты созданы.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())


